selector_to_html = {"a[href=\"#tle\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">TLE \u5728\u7f16\u8bd1\u8fc7\u7a0b\u4e2d\u7684\u5904\u7406<a class=\"headerlink\" href=\"#tle\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#tle-litetle-struct-tle-raw\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">TLE-Lite\u3001TLE-Struct \u548c TLE-Raw<a class=\"headerlink\" href=\"#tle-litetle-struct-tle-raw\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd TLE-Lite\u3001TLE-Struct \u548c TLE-Raw \u4ee5\u53ca\u5b83\u4eec\u5728\u7f16\u8bd1\u8fc7\u7a0b\u4e2d\u7684\u5904\u7406\u65b9\u5f0f\u3002</p>", "a[href=\"../../user_guide/use-tle-raw.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-Raw<a class=\"headerlink\" href=\"#tle-raw\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-Raw\u3002TLE-Raw \u5728 trition_3.6.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p><p>TLE Raw \u4e3a Triton \u63d0\u4f9b\u4e86\u4f4e\u7ea7\u6269\u5c55\u63a5\u53e3\uff0c\u5141\u8bb8\u7528\u6237\u901a\u8fc7\u7b2c\u4e09\u65b9\u65b9\u8a00\u548c\u8bed\u8a00\uff08\u4f8b\u5982\u4f7f\u7528 CUDA \u8fdb\u884c\u7ebf\u7a0b\u7ea7\u8c03\u5ea6\u3001\u540c\u6b65\u548c\u5185\u5b58\u8bbf\u95ee\uff09\u6765\u586b\u8865\u80fd\u529b\u7a7a\u767d\u5e76\u83b7\u5f97\u7ec6\u7c92\u5ea6\u63a7\u5236\u3002\u7528\u6237\u53ef\u4ee5\u6839\u636e\u76ee\u6807\u786c\u4ef6\u548c\u5de5\u5177\u94fe\u6210\u719f\u5ea6\uff0c\u5728\u53ef\u79fb\u690d\u6027\u548c\u53ef\u7ec4\u5408\u4f18\u5316\uff08\u901a\u8fc7 MLIR \u65b9\u8a00\u96c6\u6210\uff09\u4e0e\u6700\u5927\u7ec6\u7c92\u5ea6\u63a7\u5236\uff08\u901a\u8fc7 CUDA \u96c6\u6210\uff09\u4e4b\u95f4\u8fdb\u884c\u9009\u62e9\u3002</p>", "a[href=\"../../user_guide/use-tle-lite.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-Lite<a class=\"headerlink\" href=\"#tle-lite\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-Lite\u3002TLE-Lite \u5728 trition_3.6.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p>", "a[href=\"#id1\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">TLE-Lite\u3001TLE-Struct \u548c TLE-Raw \u7b80\u4ecb<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h2><p>TLE-Lite\u3001TLE-Struct \u548c TLE-Raw \u662f\u7f16\u8bd1\u5668\u8bed\u8a00\uff0c\u4f4d\u4e8e AI \u751f\u6001\u7cfb\u7edf\u7684\u4e2d\u95f4\u5c42\u3002\u4e0a\u5c42\u901a\u8fc7\u56fe\u7f16\u8bd1\u5668\u548c\u7b97\u5b50\u5e93\u8fde\u63a5 AI \u6846\u67b6\uff0c\u4e0b\u5c42\u8fde\u63a5\u5404\u79cd\u786c\u4ef6\u8fd0\u884c\u65f6\u3002</p><p>\u4e0b\u56fe\u5c55\u793a\u4e86 TLE-Lite\u3001TLE-Struct \u548c TLE-Raw \u5728 AI \u751f\u6001\u7cfb\u7edf\u4e2d\u7684\u4f4d\u7f6e\u3002</p>", "a[href=\"#gpu-commonir-lowering\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u53ef\u9009\u7684 GPU CommonIR Lowering<a class=\"headerlink\" href=\"#gpu-commonir-lowering\" title=\"Link to this heading\">#</a></h2><p>\u9ed8\u8ba4\u7684 NVIDIA \u6784\u5efa\u4fdd\u7559\u539f\u751f TLE GPU Lowering \u8def\u5f84\u3002\u663e\u5f0f\u5f00\u542f CommonIR \u540e\uff0c\u524d\u7aef\u5148\u5c06\u7ed3\u6784\u5316 buffer \u64cd\u4f5c\u4fdd\u7559\u4e3a CommonIR TileIR\uff0c\u518d\u8f6c\u6362\u4e3a\u539f\u751f TTGIR\uff1a</p>", "a[href=\"../../user_guide/use-tle-struct.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u4f7f\u7528 TLE-Struct<a class=\"headerlink\" href=\"#tle-struct\" title=\"Link to this heading\">#</a></h1><p>\u672c\u8282\u4ecb\u7ecd\u5982\u4f55\u4f7f\u7528 TLE-Struct\u3002TLE-Struct \u5728 trition_3.6.x \u5206\u652f\u4e0a\u53ef\u7528\u3002</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
